let segmentationGroup=['SEGMENT 3','SEGMENT 5'];
function segmentationImplication(ids){
 const names=ids.map(id=>id.split(' ')[1]).join(', ');
 if(ids.length===0)return 'Keep Segment 3 as the Brand + Experience anchor; no additional segment selected.';
 if(['SEGMENT 2','SEGMENT 4','SEGMENT 5'].every(id=>ids.includes(id)))return `Targeting segments ${names} suggests a strong in-store offer: breadth and retail access for 2, mixed-channel convenience for 4, and a distinctive shopping experience for 5—not ambience alone.`;
 if(ids.includes('SEGMENT 5')&&ids.includes('SEGMENT 6'))return `Targeting segments ${names} suggests an Experience-led in-store offer, with reliable convenience for 5 and credible value plus retail access for 6; do not turn Brand spending into a price war.`;
 if(ids.includes('SEGMENT 6'))return `Targeting segments ${names} suggests a value-conscious, accessible in-store experience; retail reach and fair prices matter alongside Experience, while Brand alone is a weak acquisition argument.`;
 if(ids.includes('SEGMENT 2'))return `Targeting segments ${names} suggests a breadth-led, accessible in-store offer; stock availability and convenience matter more than upgrading ambience alone.`;
 if(ids.includes('SEGMENT 4'))return `Targeting segments ${names} suggests a coordinated store-and-online offer with credible value, not an Experience-only campaign.`;
 return `Targeting segments ${names} suggests an Experience-led extension of Segment 3, backed by dependable convenience; stronger Brand fit remains concentrated in Segment 3.`;
}
